  const privateKey = store.get('privateKey') as string;
  const csid       = store.get('csid') as string;

  // ── 2. XML 생성 ──
  const xml = buildInvoiceXml({
    uuid: uuidv4(),
    icv,
    pih,
    ...orderData,
  });

  // ── 3. 서명 ──
  const signedXml = signInvoiceXml(xml, privateKey, csid);

  // ── 4. 해시 (다음 PIH용) ──
  const invoiceHash = computeInvoiceHash(signedXml);

  // ── 5. QR 생성 ──
